effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1.0 - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.0,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      #define hue(h) clamp( abs( fract(h + vec4(3,2,1,0)/3.0) * 6.0 - 3.0) -1.0 , 0.0, 1.0)

      float hash12(vec2 p)
      {
          vec3 p3  = fract(vec3(p.xyx) * 0.1031);
          p3 += dot(p3, p3.yzx + 33.33);
          return fract((p3.x + p3.y) * p3.z);
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.0, 1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

         highp mat3 rgb2yuv = mat3(
              0.299,     0.587,    0.114,
             -0.14713,  -0.28886,  0.436,
              0.615,    -0.51499, -0.10001
         );
         highp mat3 yuv2rgb = mat3(
             1.0,  0.0,      1.13983,
             1.0, -0.39465, -0.58060,
             1.0,  2.03211,  0.0
         );

 	vec4 fragColor;

          vec2 uv = umefx;
          vec3 col = vec3(0.0); 


          for(float layer =1.0; layer <= TOTAL_LAYERS; layer++ ) {

              float SIZE = (15.0 - layer) * 0.5;
              vec2 luv = uv * SIZE;
          	vec2 id = floor(luv);
          	luv = fract(luv) - 0.5;

              for(float y =- 1.0; y <= 1.0; y++ ) {
              	for(float x =- 1.0; x <= 1.0; x++ ) {
                      vec2 rid = id - vec2(x, y);

                      float rFactor1 = hash12(rid + 542.0 * layer);
                      float rFactor2 = hash12(rid + 159.0 * layer);

                      float t = iTime*5.5/(10.0 + layer*5.0/rFactor1) + 100.0 * rFactor2;

                      vec2 ruv = luv + vec2(x, y) +                 
                          vec2(
                              sin(iTime*0.1 + t + rFactor1),
                              sin(iTime*0.2 + t*0.9 + rFactor2)                    
                          );            

                      float l = length(ruv);            
                      float ld = length(ruv - vec2(0.075));  

                      float SF = 1.0/min(iResolution.x,iResolution.y)*SIZE*(layer*2.0);

                      float d = smoothstep(SF,-SF,l-(0.125 + hash12(rid + 700.0)*0.25));      

                      // Remove some bubbles to make breath space
                      d *= step(hash12(rid*75.4 + 100.0), 0.5 + (layer/TOTAL_LAYERS));

                      // Determine bubble color factor
                      float colFactor = hash12(rid + 500.0); // + iTime*0.1;

                      vec3 iCol = hue(colFactor).rgb * d * (0.7 + smoothstep(0.1,.5,ld)*1.0);

                      col += iCol*( 0.75 + (1.0 - layer/TOTAL_LAYERS)*0.2); 

              	} } }

          fragColor = vec4(col, 0.0);

 	    vec4 factorx = newLayer(texColorX,fragColor);

         vec4 baseColor = factorx;
         vec3 yuv = baseColor.rgb*rgb2yuv;

         float low = (1.0 - smoothstep(0.222, 0.444, yuv.x));
         float midLow = smoothstep(0.222, 0.444, yuv.x)*step(yuv.x, 0.555);
         float midHigh = (1.0-smoothstep(0.555, 0.777, yuv.x))*step(0.555, yuv.x) * step(yuv.x, 0.777);
         float high = smoothstep(0.555, 0.777, yuv.x);
         vec3 filter = vec3(crLow, mgLow, ybLow) * low + vec3(crMid, mgMid, ybMid)*(midLow+midHigh)+vec3(crHigh, mgHigh, ybHigh)*high;
         filter = max(min(filter, 100.0), -100.0);
         vec3 conv = (filter+vec3(100.0))/100.0;
         vec3 converted = baseColor.rgb*conv;
         vec3 convYuv = converted*rgb2yuv;
         convYuv.x = yuv.x;
         vec4 factor = vec4(convYuv*yuv2rgb, baseColor.a);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
